class ParseException(Exception):
    def __init__(self, message=None, cause=None):
        if isinstance(message, Exception) and cause is None:
            super().__init__(str(message))
            self.cause = message
        else:
            super().__init__(message)
            self.cause = cause

    @staticmethod
    def wrap(e):
        if isinstance(e, UnsupportedOperationException):
            raise e
        if isinstance(e, ParseException):
            return e
        return ParseException(e)

class UnsupportedOperationException(Exception):
    pass

class UnrecognizedOptionException(ParseException):
    def __init__(self, message, option=None):
        super().__init__(message)
        self.option = option

    def getOption(self):
        return self.option

class AmbiguousOptionException(UnrecognizedOptionException):
    @staticmethod
    def _create_message(option, matchingOptions):
        buf = ["Ambiguous option: '", option, "'  (could be: "]
        first = True
        for opt in matchingOptions:
            if not first:
                buf.append(", ")
            buf.append("'")
            buf.append(opt)
            buf.append("'")
            first = False
        buf.append(")")
        return "".join(buf)

    def __init__(self, option, matchingOptions):
        super().__init__(AmbiguousOptionException._create_message(option, matchingOptions), option)
        self.matchingOptions = list(matchingOptions)

    def getMatchingOptions(self):
        return self.matchingOptions

class MissingArgumentException(ParseException):
    def __init__(self, option_or_message):
        if isinstance(option_or_message, Option):
            super().__init__("Missing argument for option: " + option_or_message.getKey())
            self.option = option_or_message
        else:
            super().__init__(str(option_or_message))
            self.option = None

    def getOption(self):
        return self.option

class MissingOptionException(ParseException):
    @staticmethod
    def _create_message(missingOptions):
        buf = ["Missing required option", "" if len(missingOptions) == 1 else "s", ": "]
        first = True
        for opt in missingOptions:
            if not first:
                buf.append(", ")
            buf.append(str(opt))
            first = False
        return "".join(buf)

    def __init__(self, missingOptions_or_message):
        if isinstance(missingOptions_or_message, list):
            super().__init__(MissingOptionException._create_message(missingOptions_or_message))
            self.missingOptions = missingOptions_or_message
        else:
            super().__init__(str(missingOptions_or_message))
            self.missingOptions = None

    def getMissingOptions(self):
        return self.missingOptions

class AlreadySelectedException(ParseException):
    def __init__(self, group_or_message, option=None):
        if isinstance(group_or_message, str) and option is None:
            super().__init__(group_or_message)
            self.group = None
            self.option = None
        else:
            group = group_or_message
            msg = f"The option '{option.getKey()}' was specified but an option from this group has already been selected: '{group.getSelected()}"
            super().__init__(msg)
            self.group = group
            self.option = option

    def getOption(self):
        return self.option

    def getOptionGroup(self):
        return self.group

class OptionValidator:
    ADDITIONAL_OPTION_CHARS = ['?', '@']
    ADDITIONAL_LONG_CHARS = ['-']

    @staticmethod
    def _isValidChar(c):
        return c.isalnum() or c == '_' or c in OptionValidator.ADDITIONAL_LONG_CHARS

    @staticmethod
    def _isValidOpt(c):
        return c.isalnum() or c == '_' or c in OptionValidator.ADDITIONAL_OPTION_CHARS

    @staticmethod
    def validate(option):
        if option is None:
            return None
        if len(option) == 0:
            raise ValueError("Empty option name.")
        ch0 = option[0]
        if not OptionValidator._isValidOpt(ch0):
            raise ValueError(f"Illegal option name '{ch0}'.")
        if len(option) > 1:
            for ch in option[1:]:
                if not OptionValidator._isValidChar(ch):
                    raise ValueError(f"The option '{option}' contains an illegal character : '{ch}'.")
        return option

class Util:
    @staticmethod
    def isEmpty(val):
        if val is None:
            return True
        if isinstance(val, (list, tuple, str)):
            return len(val) == 0
        return False

    @staticmethod
    def stripLeadingAndTrailingQuotes(str_val):
        if Util.isEmpty(str_val):
            return str_val
        length = len(str_val)
        if length > 1 and str_val.startswith('"') and str_val.endswith('"') and str_val[1:length-1].find('"') == -1:
            return str_val[1:length-1]
        return str_val

    @staticmethod
    def stripLeadingHyphens(str_val):
        if Util.isEmpty(str_val):
            return str_val
        if str_val.startswith("--"):
            return str_val[2:]
        if str_val.startswith("-"):
            return str_val[1:]
        return str_val

