class Options:
    def __init__(self):
        self.shortOpts = {}
        self.longOpts = {}
        self.requiredOpts = []
        self.optionGroups = {}

    def addOption(self, opt, *args):
        if isinstance(opt, Option):
            key = opt.getKey()
            if opt.hasLongOpt():
                self.longOpts[opt.getLongOpt()] = opt
            if opt.isRequired():
                if key in self.requiredOpts:
                    self.requiredOpts.remove(key)
                self.requiredOpts.append(key)
            self.shortOpts[key] = opt
            return self
        elif isinstance(opt, str):
            if len(args) == 1:
                hasArg = False
                description = args[0]
                return self.addOption(Option(opt, None, hasArg, description))
            elif len(args) == 2:
                hasArg = args[0]
                description = args[1]
                return self.addOption(Option(opt, None, hasArg, description))
            elif len(args) == 3:
                longOpt = args[0]
                hasArg = args[1]
                description = args[2]
                return self.addOption(Option(opt, longOpt, hasArg, description))
        return self

    def addOptionGroup(self, group):
        if group.isRequired():
            self.requiredOpts.append(group)
        for option in group.getOptions():
            option.setRequired(False)
            self.addOption(option)
            self.optionGroups[option.getKey()] = group
        return self

    def addOptions(self, options):
        for opt in options.getOptions():
            if self.hasOption(opt.getKey()):
                raise ValueError("Duplicate key: " + opt.getKey())
            self.addOption(opt)
        for group in options.getOptionGroups():
            self.addOptionGroup(group)
        return self

